const $=s=>document.querySelector(s);
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected='todo-broken',current=null,samples=[];
const label=v=>({FAIL:'REGRESSION REPRODUCED',PASS:'DECLARED CHECK PASSED',INCOMPLETE:'INCOMPLETE EVIDENCE',NO_DEPENDENCY_SELECTED:'NO CHECK SELECTED',error:'RUN ERROR',queued:'QUEUED',running:'RUNNING'}[v]||v);
const pill=v=>`<span class="pill ${escapeHtml(v.toLowerCase())}">${escapeHtml(label(v))}</span>`;
async function request(path,options){const r=await fetch(path,options);const body=await r.json();if(!r.ok)throw Error(body.error||r.statusText);return body;}
function renderSamples(){
 const item=s=>`<button class="sample" type="button" role="radio" tabindex="${selected===s.id?0:-1}" aria-checked="${selected===s.id}" data-sample="${escapeHtml(s.id)}"><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.description)}</small></button>`;
 const primary=samples.filter(s=>['todo-broken','todo-fixed'].includes(s.id));
 const more=samples.filter(s=>!['todo-broken','todo-fixed'].includes(s.id));
 $('#samples').innerHTML=primary.map(item).join('')+(more.length?`<details class="sample-more" ${more.some(s=>s.id===selected)?'open':''}><summary>More examples and recorded workflows (${more.length})</summary>${more.map(item).join('')}</details>`:'');
 const buttons=[...$('#samples').querySelectorAll('[data-sample]')];
 if(!selected&&buttons.length)buttons[0].tabIndex=0;
 const select=(button,focus=false)=>{selected=button.dataset.sample;$('#folder').value='';renderSamples();if(focus)$('#samples').querySelector(`[data-sample="${CSS.escape(selected)}"]`).focus();};
 buttons.forEach(button=>{button.onclick=()=>select(button,true);button.onkeydown=e=>{if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const visible=buttons.filter(b=>b.getClientRects().length);const next=(visible.indexOf(button)+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+visible.length)%visible.length;select(visible[next],true);};});
}
async function refreshRunHistory(){const runs=await request('/api/runs');$('#history').innerHTML=runs.length?runs.slice(0,12).map(r=>`<button class="history-item" data-run="${escapeHtml(r.id)}"><div class="history-row"><strong>${escapeHtml(r.folder.split(/[\\/]/).pop())}</strong>${pill(r.verdict||r.status)}</div><small>${escapeHtml(r.id)}</small></button>`).join(''):'<p class="fine">No runs yet. Your first investigation appears here.</p>';$('#history').querySelectorAll('button').forEach(b=>b.onclick=()=>{current=b.dataset.run;const url=new URL(location);url.searchParams.set('run',current);window.history.replaceState(null,'',url);poll(current);});}
function renderResult(r){
 $('#result').dataset.verdict=r.verdict;
 const base=`/artifacts/${encodeURIComponent(r.id)}/`;
 const title={FAIL:'The old behavior did not survive.',PASS:'The declared behavior survived.',INCOMPLETE:'There is not enough evidence.',NO_DEPENDENCY_SELECTED:'No dependent check was selected.'}[r.verdict];
 const paths=r.paths.map(p=>`<div class="path"><div class="node writer"><small>Changed writer</small>${escapeHtml(p[0])}</div><span class="arrow" aria-hidden="true">→</span><div class="node"><small>Writes storage key</small>${escapeHtml(p[1])}</div><span class="arrow" aria-hidden="true">←</span><div class="node"><small>Read by</small>${escapeHtml(p[2])}</div><span class="arrow" aria-hidden="true">→</span><div class="node"><small>Feature to check</small>${escapeHtml(p[3])}</div></div>`).join('');
 const checks=r.checks.map(c=>`<article class="check preservation-check"><h3>${escapeHtml(c.feature)} ${pill(c.verdict)}</h3><div class="comparison"><div class="state"><span>Old build · after reload</span><ul>${c.before.map(v=>`<li class="${!c.after_reload.includes(v)?'missing-observation':''}">${escapeHtml(v)}${!c.after_reload.includes(v)?'<span class="missing-label">Missing after change</span>':''}</li>`).join('')}</ul><a href="${base}baseline.png" target="_blank" rel="noopener"><img width="1280" height="720" loading="lazy" src="${base}baseline.png" alt="Old build with saved data"></a></div><div class="state ${c.verdict==='FAIL'?'changed':'preserved'}"><span>Changed build · after action and reload</span>${c.after_reload.length?`<ul>${c.after_reload.map(v=>`<li>${escapeHtml(v)}</li>`).join('')}</ul>`:'<p class="nothing">Previously observed items are missing.</p>'}<a href="${base}${encodeURIComponent(c.screenshot)}" target="_blank" rel="noopener"><img width="1280" height="720" loading="lazy" src="${base}${encodeURIComponent(c.screenshot)}" alt="New build after the changed feature and reload"></a></div></div><details class="reproduction"><summary>Inspect reproducing actions</summary><ol class="steps">${c.steps.map(s=>`<li>${escapeHtml(s)}</li>`).join('')}</ol><p class="fine">${c.original_actions.length} → ${c.minimal_actions.length} changed-feature actions after ${c.reduction_replays} extra browser replays. ${c.verdict==='FAIL'?'Deletion-minimal for this order.':'No failure reduction was needed for this passing check.'}</p>${c.errors.length?`<pre>${escapeHtml(c.errors.join('\n'))}</pre>`:''}</details></article>`).join('');
 const agentPanel=r.agent?.requested?`<section class="check agent-trail"><h3>Agent tool trail</h3><p class="fine">Real local-model decisions; each tool and target is validated. Browser assertions determine the verdict.</p>${r.agent.steps.map(event=>event.decision?`<div class="path" style="display:block"><strong>${escapeHtml(event.step)}. ${escapeHtml(event.decision.tool)}${event.decision.target?' → '+escapeHtml(event.decision.target):''}</strong><p class="fine">${escapeHtml(event.explanation||"Older run: model prose was not evidence.")}</p><details><summary>Tool result</summary><pre>${escapeHtml(JSON.stringify(event.result,null,2))}</pre></details></div>`:`<p class="notice">${escapeHtml(event.skipped||'Agent step unavailable')}</p>`).join('')}</section>`:'';
 $('#result').innerHTML=`<div class="result-head"><div><div class="kicker">Run ${escapeHtml(r.id)}</div><h2>${escapeHtml(title)}</h2>${pill(r.verdict)}</div><div class="exports"><a href="${base}report.md" download="parivartanparakh-${escapeHtml(r.id)}.md">↓ Markdown report</a><a href="${base}evidence.json" download="parivartanparakh-${escapeHtml(r.id)}.json">↓ Raw evidence</a></div></div><div class="stats"><span><strong>${r.changed_modules.length}</strong> changed modules</span><span><strong>${r.traces.length}</strong> storage operations</span><span><strong>${r.selected_checks.length}</strong> selected checks</span></div>${r.provenance?`<details class="notice provenance"><summary>Controlled injected regression · upstream attribution</summary><p>${escapeHtml(r.provenance.disclosure)}</p><p>Upstream commit: ${escapeHtml(r.provenance.commit)}</p></details>`:""}${r.retained_targets?.length?`<div class="notice">Retained regression case requires replay of: ${escapeHtml(r.retained_targets.join(", "))}. This obligation is queried from FalkorDB even when the current edit has no shared-key impact path.</div>`:""}<h3>Why these checks?</h3>${paths||'<p class="fine">The Cypher query returned no writer → key → reader → feature path. This is not an app-wide safety verdict.</p>'}${r.issues.length?`<div class="notice"><strong>Evidence limits</strong><ul>${r.issues.map(i=>`<li>${escapeHtml(i)}</li>`).join('')}</ul></div>`:''}${checks}${agentPanel}<details><summary>Inspect query, graph and source revisions</summary><p class="fine">FalkorDB graph: <strong>${escapeHtml(r.graph)}</strong></p><pre>${escapeHtml(r.query)}</pre><pre>${escapeHtml(JSON.stringify(r.source_hashes,null,2))}</pre></details><p class="fine" style="margin-top:20px">${escapeHtml(r.scope)} Actions and preservation requirements are declared. ${r.agent?.requested?'The local model selected tools; it did not issue the verdict.':'Deterministic mode; no model was used.'}</p>`;
 window.renderRepairControls?.(r);
}
async function poll(id){try{const job=await request('/api/runs/'+encodeURIComponent(id));if(current!==id)return;if(job.status==='complete'){renderResult(job.result);$('#run').disabled=false;await refreshRunHistory();return;}if(job.status==='error'){$('#result').innerHTML=`<div class="progress">${pill('error')}<h2>The investigation could not complete.</h2><p class="error">${escapeHtml(job.error)}</p><p class="fine">No passing verdict was issued.</p></div>`;$('#run').disabled=false;await refreshRunHistory();return;}$('#result').innerHTML=`<div class="progress"><div class="eyebrow"><span class="pulse"></span>Investigation ${escapeHtml(job.status)}…</div><h2>${escapeHtml(job.phase)}</h2><p class="fine">Running a fresh browser investigation. No prerecorded verdict.</p></div>`;setTimeout(()=>{if(current===id)poll(id);},650);}catch(error){$('#launch-error').textContent=error.message;$('#run').disabled=false;}}
$('#run').onclick=async()=>{ $('#launch-error').textContent='';$('#run').disabled=true;try{const folder=$('#folder').value.trim();const job=await request('/api/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...folder?{folder}:{sample:selected},ablate:$('#ablate').checked,agent:$('#agent-mode').checked})});current=job.id;poll(current);refreshRunHistory();$('#result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}catch(error){$('#launch-error').textContent=error.message;$('#run').disabled=false;} };
$('#folder').oninput=()=>{if($('#folder').value.trim()){selected=null;renderSamples();}};
(async()=>{try{samples=await request('/api/samples');renderSamples();await refreshRunHistory();const linkedRun=new URLSearchParams(location.search).get('run');if(linkedRun){current=linkedRun;await poll(current);}}catch(error){$('#launch-error').textContent=error.message;}})();
